def confronta(ordine, ddt, fattura, tolleranza=1.0):
    paga, fuori, mancanti = 0, 0, 0
    for o, b, f in zip(ordine, ddt, fattura):
        q = min(o['q'], b['q'])
        mancanti += b['q'] < o['q']
        if abs(f['prezzo'] - o['prezzo']) <= tolleranza:
            prezzo = f['prezzo']
        else:
            prezzo, fuori = o['prezzo'], fuori + 1
        paga += q * prezzo
    esito = 'contesta' if fuori else ('approva parzialmente' if mancanti else 'approva')
    return {'importo_da_pagare': round(paga, 2), 'esito': esito}
